import{_ as e,o as n,c as i,a3 as s}from"./chunks/framework.DFRwgAh-.js";const g=JSON.parse('{"title":"視覚的回帰検証およびセレクター自己修復","description":"Vision AIによる視覚的レイアウト完全性検証と、UI変更時に壊れたDOMセレクターを検知・復旧する自己修復パイプラインを説明します。","frontmatter":{"title":"視覚的回帰検証およびセレクター自己修復","description":"Vision AIによる視覚的レイアウト完全性検証と、UI変更時に壊れたDOMセレクターを検知・復旧する自己修復パイプラインを説明します。","sort":900,"head":[["link",{"rel":"canonical","href":"https://empasy.io/docs/ja/synceta/self-healing-and-vision.html"}]]},"headers":[],"relativePath":"ja/synceta/self-healing-and-vision.md","filePath":"ja/synceta/self-healing-and-vision.md","lastUpdated":1787704557000}'),t={name:"ja/synceta/self-healing-and-vision.md"};function l(o,a,r,h,d,c){return n(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="視覚的回帰検証およびセレクター自己修復" tabindex="-1">視覚的回帰検証およびセレクター自己修復 <a class="header-anchor" href="#視覚的回帰検証およびセレクター自己修復" aria-label="Permalink to “視覚的回帰検証およびセレクター自己修復”">​</a></h1><p>フロントエンドの頻繁なリリースに伴うセレクター破損やレイアウト崩れに対し、SyncETAは<strong>Vision AI視覚検証</strong>と<strong>セレクター自己修復（Self-Healing）</strong>を提供します。</p><hr><h2 id="_1-vision-aiベースの視覚的回帰検証" tabindex="-1">1. Vision AIベースの視覚的回帰検証 <a class="header-anchor" href="#_1-vision-aiベースの視覚的回帰検証" aria-label="Permalink to “1. Vision AIベースの視覚的回帰検証”">​</a></h2><p>ピクセル単位の差分比較における誤検知を解消し、人間の認知観点で異常を判定します。</p><ul><li><strong>要素重複検知</strong>: ポップアップやバナーが重要な購入ボタン等を隠している現象を検知。</li><li><strong>テキスト欠け検知</strong>: レスポンシブ切り替え時に文字が枠外にはみ出る不具合を検出。</li><li><strong>除外領域設定</strong>: 現在時刻や広告バナーなど動的エリアを比較対象から除外。</li></ul><hr><h2 id="_2-セレクター自己修復-self-healing" tabindex="-1">2. セレクター自己修復（Self-Healing） <a class="header-anchor" href="#_2-セレクター自己修復-self-healing" aria-label="Permalink to “2. セレクター自己修復（Self-Healing）”">​</a></h2><p>UI変更により既存のXPathやCSSセレクターが一致しなくなった場合、ビジョンモデルが要素の視覚位置を特定し、新しいDOMパスを算出します。</p><ul><li><strong>管理者承認ガバナンス（Human-in-the-Loop）</strong>: AIが勝手にテストスクリプトを変更するリスクを防止し、管理者が承認した後にテスト資産へ反映されます。</li></ul>',10)])])}const f=e(t,[["render",l]]);export{g as __pageData,f as default};
